import{_ as e,c as s,o as a,j as i,Y as o,t as r}from"./chunks/framework.BNTND4LZ.js";const m=JSON.parse('{"title":"docker-network-connect | x-cmd man (docker man1) | Connect a container to a network","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-network-connect - Connect a container to a network","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-network-connect | x-cmd man (docker man1) | Connect a container to a network"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-network-connect - Connect a container to a network"}]]},"headers":[],"params":{"isMan":true,"man":"docker-network-connect","category":"docker man1","desc":"Connect a container to a network"},"relativePath":"docker/man1/docker-network-connect.md","filePath":"docker/man1/[man].md"}'),c={name:"docker/man1/docker-network-connect.md"},h={class:"visually-hidden"};function k(t,n,p,l,d,g){return a(),s("div",null,[i("h1",h,r(t.$params.man),1),n[0]||(n[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-network-connect - Connect a container to a network</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker network connect [OPTIONS] NETWORK CONTAINER</strong></p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Connects a container to a network. You can connect a container by name or by ID. Once connected, the container can communicate with other containers in the same network.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi-host-network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container1</span></span></code></pre></div><p>You can also use the <strong>docker run --network=&lt;network-name&gt;</strong> option to start a container and immediately connect it to a network.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -itd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --network=multi-host-network</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.20.88.22</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ip6</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 2001:db8::8822</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> busybox</span></span></code></pre></div><p>You can pause, restart, and stop containers that are connected to a network. A container connects to its configured networks when it runs.</p><p>If specified, the container&#39;s IP address(es) is reapplied when a stopped container is restarted. If the IP address is no longer available, the container fails to start. One way to guarantee that the IP address is available is to specify an <strong>--ip-range</strong> when creating the network, and choose the static IP address(es) from outside that range. This ensures that the IP address is not given to another container while this container is not on the network.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --subnet</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.20.0.0/16</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ip-range</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 172.20.240.0/20</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi-host-network</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 172.20.128.2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> multi-host-network</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container2</span></span></code></pre></div><p>To verify the container is connected, use the <strong>docker network inspect</strong> command. Use <strong>docker network disconnect</strong> to remove a container from the network.</p><p>Once connected in network, containers can communicate using only another container&#39;s IP address or name. For <strong>overlay</strong> networks or custom plugins that support multi-host connectivity, containers connected to the same multi-host network but launched from different Engines can also communicate in this way.</p><p>You can connect a container to one or more networks. The networks need not be the same type. For example, you can connect a single container bridge and overlay networks.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>--alias</strong>=[] Add network-scoped alias for the container</p><p><strong>--driver-opt</strong>=[] driver options for the network</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for connect</p><p><strong>--ip</strong>=&quot;&quot; IPv4 address (e.g., &quot;172.30.100.104&quot;)</p><p><strong>--ip6</strong>=&quot;&quot; IPv6 address (e.g., &quot;2001:db8::33&quot;)</p><p><strong>--link</strong>= Add link to another container</p><p><strong>--link-local-ip</strong>=[] Add a link-local address for the container</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-network(1)</strong></p>`,25))])}const u=e(c,[["render",k]]);export{m as __pageData,u as default};
